        for r in range(h):
            for c in range(w):
                p[r + 1][c + 1] = (
                    p[r][c + 1] + p[r + 1][c] - p[r][c]
                    + (grid[r][c] != color)
                )

        def solid(r0, r1, c0, c1):
            return (p[r1 + 1][c1 + 1] - p[r0][c1 + 1]
                    - p[r1 + 1][c0] + p[r0][c0]) == 0

        for r0 in range(h):
            for r1 in range(r0 + 4, h):
                for c0 in range(w):
                    for c1 in range(c0 + 4, w):
                        if not solid(r0, r1, c0, c1):
                            continue
                        # Keep rectangles that cannot be extended along a side.
                        extend = (
                            (r0 > 0 and solid(r0 - 1, r1, c0, c1)) or
                            (r1 + 1 < h and solid(r0, r1 + 1, c0, c1)) or
                            (c0 > 0 and solid(r0, r1, c0 - 1, c1)) or
                            (c1 + 1 < w and solid(r0, r1, c0, c1 + 1))
                        )
                        if not extend:
                            rectangles.append((r0, r1, c0, c1, color))

    # Discard any locally maximal rectangle contained in a larger candidate.
    keep = []
    for i, a in enumerate(rectangles):
        r0, r1, c0, c1, color = a
        contained = any(
            i != j and b[4] == color and
